import React, { useState } from 'react';
import { Toolbar, Drawer, List, ListItem, ListItemText, Box } from '@mui/material';
import { useNavigate, useLocation } from 'react-router-dom';

const NavBar = () => {
  const location = useLocation();
  const [selected, setSelected] = useState(location.pathname.replace('/', ''));
  const navigate = useNavigate();

  const handleMenuClick = (id) => {
    setSelected(id);
    navigate(id === 'home' ? '/' : `/${id}`);
  };

  return (
    <Drawer
      variant="permanent"
      sx={{
        width: 240,
        flexShrink: 0,
        [`& .MuiDrawer-paper`]: { width: 240, boxSizing: 'border-box' },
      }}>
      <Toolbar />
      <Box sx={{ overflow: 'auto' }}>
        <List>
          <ListItem 
            button 
            onClick={() => handleMenuClick('home')}
            selected={selected === 'home'}
          >
            <ListItemText primary="Home" />
          </ListItem>
          <ListItem 
            button 
            onClick={() => handleMenuClick('aqchart')}
            selected={selected === 'aqchart'}
          >
            <ListItemText primary="Air Quality Dashboard" />
          </ListItem>
          <ListItem 
            button 
            onClick={() => handleMenuClick('projects')}
            selected={selected === 'projects'}
          >
            <ListItemText primary="Other Projects" />
          </ListItem>
        </List>
      </Box>
    </Drawer>
  );
};

export default NavBar;